// Generated by esquadro: do not edit. Saved views of a list: its search,
// filters, period and sorting under a name ("Pending in Beauty"), to come
// back to. Kept in this browser.
import { Bookmark, BookmarkPlus, Check, Trash2 } from "lucide-react"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { base } from "../config.ts"
import { t } from "./i18n.ts"
import type { ResourceMeta } from "./meta.ts"
import { toast } from "./toast.tsx"

export type ViewSearch = Record<string, string | number | undefined>

export interface View {
  name: string
  search: ViewSearch
}

/** A list's state as a view keeps it: without its page. */
export function viewOf(search: ViewSearch): ViewSearch {
  const out: ViewSearch = {}
  for (const k of Object.keys(search).sort()) {
    if (k !== "page" && k !== "cursor" && search[k] !== undefined && search[k] !== "") out[k] = search[k]
  }
  return out
}

const same = (a: ViewSearch, b: ViewSearch) => JSON.stringify(viewOf(a)) === JSON.stringify(viewOf(b))

function storageKey(meta: ResourceMeta) {
  return `esquadro:${base}:${meta.name}:views`
}

function load(meta: ResourceMeta): View[] {
  try {
    return JSON.parse(localStorage.getItem(storageKey(meta)) ?? "[]") as View[]
  } catch {
    return []
  }
}

/** The views saved for a resource's list, and how to save and remove them. */
export function useViews(meta: ResourceMeta) {
  const [views, setViews] = useState<View[]>(() => load(meta))
  const store = (next: View[]) => {
    setViews(next)
    try {
      localStorage.setItem(storageKey(meta), JSON.stringify(next))
    } catch {
      // Storage refused (a private window): the views last the visit.
    }
  }
  return {
    views,
    save: (name: string, search: ViewSearch) => store([...views.filter((v) => v.name !== name), { name, search: viewOf(search) }]),
    remove: (name: string) => store(views.filter((v) => v.name !== name)),
  }
}

export function ViewsMenu({ meta, search, onApply }: { meta: ResourceMeta; search: ViewSearch; onApply: (search: ViewSearch) => void }) {
  const { views, save, remove } = useViews(meta)
  const [naming, setNaming] = useState(false)
  const [name, setName] = useState("")
  const current = views.find((v) => same(v.search, search))
  const saveable = Object.keys(viewOf(search)).length > 0
  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="outline">
            <Bookmark />
            {current ? current.name : t("views")}
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-64">
          <DropdownMenuLabel className="text-xs font-normal text-muted-foreground">{t("savedViews")}</DropdownMenuLabel>
          {views.length === 0 && <div className="px-2 py-1.5 text-sm text-muted-foreground">{t("noViews")}</div>}
          {views.map((v) => (
            <DropdownMenuItem key={v.name} onClick={() => onApply(v.search)} className="group/view">
              {current?.name === v.name ? <Check /> : <span className="size-4" />}
              <span className="flex-1 truncate">{v.name}</span>
              <Button
                variant="ghost"
                size="icon-xs"
                className="opacity-0 group-hover/view:opacity-100 focus-visible:opacity-100"
                aria-label={`${t("delete")} ${v.name}`}
                onClick={(e) => {
                  e.stopPropagation()
                  remove(v.name)
                  toast(t("viewDeleted"))
                }}
              >
                <Trash2 />
              </Button>
            </DropdownMenuItem>
          ))}
          <DropdownMenuSeparator />
          <DropdownMenuItem
            disabled={!saveable}
            onClick={() => {
              setName(current?.name ?? "")
              setNaming(true)
            }}
          >
            <BookmarkPlus /> {t("saveView")}
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
      <Dialog open={naming} onOpenChange={setNaming}>
        <DialogContent className="sm:max-w-sm">
          <form
            className="flex flex-col gap-4"
            onSubmit={(e) => {
              e.preventDefault()
              if (!name.trim()) return
              save(name.trim(), search)
              setNaming(false)
              toast(t("viewSaved"))
            }}
          >
            <DialogHeader>
              <DialogTitle>{t("saveView")}</DialogTitle>
              <DialogDescription>{t("saveViewHint")}</DialogDescription>
            </DialogHeader>
            <Input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder={t("viewName")} aria-label={t("viewName")} />
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setNaming(false)}>
                {t("cancel")}
              </Button>
              <Button type="submit" disabled={!name.trim()}>
                {t("save")}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  )
}
